<template>
  <div class="metric-page" v-loading="loading">
    <header class="metric-hero">
      <div><span class="eyebrow">METRIC OPERATIONS / M03 V1</span><h2>指标趋势与预警处置中心</h2><p>从八类主题趋势定位异常，下钻观测、动态基线、规则版本、告警与派单完整事实链。</p></div>
      <div class="hero-actions"><el-button :icon="Refresh" @click="loadOverview">刷新</el-button><el-button type="primary" :icon="DataAnalysis" :loading="bootstrapping" @click="bootstrapDemo">生成 V1 验收样例</el-button></div>
    </header>
    <section class="summary-strip">
      <article><span>指标定义</span><strong>{{ overview.summary.definition_count }}</strong><small>{{ overview.summary.theme_count }} / 8 个主题已覆盖</small></article>
      <article><span>动态基线</span><strong>{{ overview.summary.baseline_count }}</strong><small>历史窗口保留版本快照</small></article>
      <article :class="{ alerting: overview.summary.active_incident_count }"><span>活动预警</span><strong>{{ overview.summary.active_incident_count }}</strong><small>共 {{ overview.summary.rule_count }} 条预警规则</small></article>
      <article :class="{ alerting: overview.summary.open_order_count }"><span>待闭环派单</span><strong>{{ overview.summary.open_order_count }}</strong><small>值班与人工指派均可追溯</small></article>
    </section>
    <section class="theme-board" aria-label="八类指标主题覆盖情况">
      <article v-for="(theme, index) in overview.themes" :key="theme.theme"><span class="theme-index">{{ String(index + 1).padStart(2, '0') }}</span><div><strong>{{ theme.theme_label }}</strong><small>{{ theme.metric_count ? `${theme.metric_count} 项指标` : '等待配置' }}</small></div><i :class="{ ready: theme.metric_count > 0 }" /></article>
    </section>

    <el-card shadow="never" class="workbench"><el-tabs v-model="activeTab">
      <el-tab-pane label="趋势分析" name="analytics">
        <section class="analytics-shell" v-loading="trendLoading">
          <div class="analytics-filter">
            <el-select v-model="analyticsFilter.theme" placeholder="全部主题" clearable @change="onThemeChange"><el-option v-for="theme in overview.themes" :key="theme.theme" :label="theme.theme_label" :value="theme.theme" /></el-select>
            <el-select v-model="analyticsFilter.definition_id" placeholder="选择指标" filterable clearable><el-option v-for="item in filteredDefinitions" :key="item.id" :label="item.name" :value="item.id" /></el-select>
            <el-select v-model="analyticsFilter.device" placeholder="全部设备" clearable><el-option v-for="item in analytics.dimension_options.device" :key="item" :label="item" :value="item" /></el-select>
            <el-select v-model="analyticsFilter.network_element" placeholder="全部网元" clearable><el-option v-for="item in analytics.dimension_options.network_element" :key="item" :label="item" :value="item" /></el-select>
            <el-select v-model="analyticsFilter.time_slot" placeholder="全部时段" clearable><el-option v-for="item in analytics.dimension_options.time_slot" :key="item" :label="item" :value="item" /></el-select>
            <el-date-picker v-model="analyticsFilter.range" class="analytics-time-range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" range-separator="至" />
            <el-button type="primary" @click="loadAnalytics">查询</el-button><el-button @click="resetAnalytics">重置</el-button>
          </div>
          <div class="theme-stat-grid" aria-label="八类指标趋势概览">
            <button v-for="item in analytics.theme_stats" :key="item.theme" :class="{ active: analyticsFilter.theme === item.theme }" type="button" @click="selectTheme(item.theme)">
              <span>{{ item.theme_label }}</span><strong>{{ item.latest_value === null ? '—' : `${roundValue(item.latest_value)}${item.latest_unit}` }}</strong><small>{{ item.observation_count }} 次观测 · {{ item.alert_count }} 次预警</small>
            </button>
          </div>
          <div class="trend-summary">
            <article><span>观测数</span><strong>{{ analytics.summary.observation_count }}</strong></article><article><span>平均值</span><strong>{{ displayNumber(analytics.summary.average_value) }}</strong></article><article><span>最小 / 最大</span><strong>{{ displayNumber(analytics.summary.minimum_value) }} / {{ displayNumber(analytics.summary.maximum_value) }}</strong></article><article :class="{ alerting: analytics.summary.alert_count }"><span>规则命中</span><strong>{{ analytics.summary.alert_count }}</strong></article>
          </div>
          <section class="trend-panel">
            <div class="trend-heading"><div><small>OBSERVATION TREND</small><h3>{{ analytics.selected_definition?.name || '暂无可展示指标' }}</h3></div><span>实线为观测值，虚线为动态基线与阈值；点击数据点查看事实链。</span></div>
            <div ref="trendChartRef" class="trend-chart" role="img" :aria-label="`${analytics.selected_definition?.name || '指标'}趋势图`" />
            <el-empty v-if="!analytics.points.length" description="当前筛选条件下暂无观测数据" />
          </section>
          <el-table :data="[...analytics.points].reverse()" stripe class="observation-table">
            <el-table-column label="观测时间" width="176"><template #default="{ row }">{{ datetimeFormat(row.observed_at) }}</template></el-table-column>
            <el-table-column label="观测值" width="110"><template #default="{ row }"><strong class="metric-value">{{ roundValue(row.value) }}{{ analytics.selected_definition?.unit }}</strong></template></el-table-column>
            <el-table-column label="动态基线" width="110"><template #default="{ row }">{{ displayNumber(row.baseline_mean) }}</template></el-table-column>
            <el-table-column label="关注 / 紧急阈值" width="160"><template #default="{ row }">{{ displayNumber(row.warning_threshold) }} / {{ displayNumber(row.critical_threshold) }}</template></el-table-column>
            <el-table-column label="维度" min-width="240"><template #default="{ row }"><span class="muted">{{ dimensionText(row.dimensions) }}</span></template></el-table-column>
            <el-table-column label="告警" width="105"><template #default="{ row }"><el-tag v-if="row.alert" :type="row.alert.severity === 'CRITICAL' ? 'danger' : 'warning'" effect="plain">{{ row.alert.severity === 'CRITICAL' ? '紧急' : '关注' }}</el-tag><span v-else class="muted">未命中</span></template></el-table-column>
            <el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openObservationDetail(row.id)">详情</el-button></template></el-table-column>
          </el-table>
        </section>
      </el-tab-pane>
      <el-tab-pane :label="`指标配置 ${overview.definitions.length}`" name="definitions">
        <div class="section-intro"><div><strong>指标与数据源</strong><span>连接信息只保存非敏感元数据；密码和密钥不进入配置快照。</span></div><div class="toolbar"><el-button @click="openSourceDialog()">新增数据源</el-button><el-button type="primary" @click="openDefinitionDialog()">新增指标</el-button></div></div>
        <div class="source-rack"><article v-for="source in overview.sources" :key="source.id"><div><small>{{ source.source_type_label }}</small><strong>{{ source.name }}</strong><code>{{ source.source_key }}</code></div><el-button link type="primary" @click="openSourceDialog(source)">编辑</el-button></article><div v-if="!overview.sources.length" class="rack-empty">尚未配置数据源</div></div>
        <el-table :data="overview.definitions" stripe>
          <el-table-column label="主题 / 指标" min-width="250"><template #default="{ row }"><div class="primary-cell"><small>{{ row.theme_label }}</small><strong>{{ row.name }}</strong><code>{{ row.metric_key }}</code></div></template></el-table-column>
          <el-table-column label="最新值" width="130"><template #default="{ row }"><strong class="metric-value">{{ metricValue(row) }}</strong></template></el-table-column>
          <el-table-column label="声明维度" min-width="230"><template #default="{ row }"><span class="muted">{{ row.dimensions_schema.join(' · ') || '全局' }}</span></template></el-table-column>
          <el-table-column label="采集时间" width="176"><template #default="{ row }">{{ row.observed_at ? datetimeFormat(row.observed_at) : '—' }}</template></el-table-column>
          <el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" @click="openDefinitionDialog(row)">编辑</el-button></template></el-table-column>
        </el-table><el-empty v-if="!overview.definitions.length" description="新建指标，或生成八类主题验收样例" />
      </el-tab-pane>

      <el-tab-pane :label="`预警规则 ${overview.rules.length}`" name="rules">
        <div class="section-intro"><div><strong>版本化预警配置</strong><span>每次保存产生新版本；合规失败的版本保留但不会参与计算。</span></div><el-button type="primary" @click="openRuleDialog()">新增规则</el-button></div>
        <el-table :data="overview.rules" stripe>
          <el-table-column label="规则" min-width="250"><template #default="{ row }"><div class="primary-cell"><small>{{ row.theme_label }}</small><strong>{{ row.name }}</strong><span>{{ row.metric_name }}</span></div></template></el-table-column>
          <el-table-column label="策略" min-width="250"><template #default="{ row }"><div class="primary-cell"><strong>{{ row.mode_label }}</strong><span v-if="row.mode === 'DYNAMIC'">窗口 {{ row.baseline_window }} · 偏差 {{ row.warning_deviation }}σ / {{ row.critical_deviation }}σ</span><span v-else>{{ row.direction_label }} {{ row.warning_threshold ?? '—' }} / {{ row.critical_threshold ?? '—' }}</span></div></template></el-table-column>
          <el-table-column label="版本" width="80"><template #default="{ row }">V{{ row.config_version }}</template></el-table-column>
          <el-table-column label="合规" width="120"><template #default="{ row }"><el-tooltip :content="row.compliance_issues.join('；')" :disabled="!row.compliance_issues.length"><el-tag :type="row.compliance_status === 'PASSED' ? 'success' : 'danger'" effect="plain">{{ row.compliance_status === 'PASSED' ? '校验通过' : '校验失败' }}</el-tag></el-tooltip></template></el-table-column>
          <el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" @click="openRuleDialog(row)">编辑</el-button></template></el-table-column>
        </el-table><el-empty v-if="!overview.rules.length" description="暂无预警规则" />
      </el-tab-pane>

      <el-tab-pane :label="`值班台历 ${overview.duty_shifts.length}`" name="duty">
        <div class="section-intro"><div><strong>值班台历</strong><span>同一处理人的重叠班次会被拦截；派单时固化命中的班次快照。</span></div><el-button type="primary" @click="openShiftDialog()">新增班次</el-button></div>
        <div class="duty-layout"><el-calendar v-model="calendarDate"><template #date-cell="{ data }"><div class="calendar-cell" :class="{ covered: shiftsForDay(data.day).length }"><span>{{ Number(data.day.slice(-2)) }}</span><small v-if="shiftsForDay(data.day).length">{{ shiftsForDay(data.day).length }} 班</small></div></template></el-calendar><aside class="shift-list"><div class="aside-heading"><small>SELECTED DAY</small><strong>{{ selectedDay }}</strong></div><article v-for="shift in selectedDayShifts" :key="shift.id"><div><strong>{{ shift.name }}</strong><span>{{ datetimeFormat(shift.starts_at) }} — {{ datetimeFormat(shift.ends_at) }}</span><small>{{ shift.assignee_name }} · {{ shift.enabled ? '生效' : '停用' }}</small></div><el-button link type="primary" @click="openShiftDialog(shift)">编辑</el-button></article><el-empty v-if="!selectedDayShifts.length" description="当天无值班安排" :image-size="72" /></aside></div>
      </el-tab-pane>

      <el-tab-pane :label="`派单闭环 ${overview.orders.length}`" name="orders">
        <div class="section-intro"><div><strong>告警处置事实链</strong><span>人工指派、转派、认领、备注和状态变化均追加记录，不覆盖历史。</span></div></div>
        <el-table :data="overview.orders" stripe>
          <el-table-column label="派单" min-width="280"><template #default="{ row }"><div class="primary-cell"><small>{{ row.theme_label }} · {{ row.metric_name }}</small><strong>{{ row.title }}</strong><span>观测 {{ row.observed_value }} / 阈值 {{ roundValue(row.threshold_value) }}</span></div></template></el-table-column>
          <el-table-column label="级别" width="90"><template #default="{ row }"><el-tag :type="row.severity === 'CRITICAL' ? 'danger' : 'warning'" effect="plain">{{ row.severity === 'CRITICAL' ? '紧急' : '关注' }}</el-tag></template></el-table-column>
          <el-table-column label="处理人" min-width="130"><template #default="{ row }">{{ row.assignee_name || '待人工指派' }}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{ row }"><el-tag effect="plain">{{ row.status_label }}</el-tag></template></el-table-column><el-table-column label="创建时间" width="176"><template #default="{ row }">{{ datetimeFormat(row.create_time) }}</template></el-table-column>
          <el-table-column label="操作" width="260" fixed="right"><template #default="{ row }"><el-button v-if="row.status === 'NEW'" link type="primary" @click="openOrderDrawer(row, 'assign')">指派</el-button><el-button v-if="row.status === 'ASSIGNED'" link type="primary" @click="operateOrder(row, 'CLAIM')">认领</el-button><el-button v-if="row.status === 'CLAIMED'" link type="primary" @click="operateOrder(row, 'START')">开始处理</el-button><el-button v-if="row.status === 'PROCESSING'" link type="success" @click="operateOrder(row, 'RESOLVE')">标记解决</el-button><el-button v-if="row.status === 'RESOLVED'" link type="success" @click="operateOrder(row, 'CLOSE')">关闭</el-button><el-button link @click="openOrderDrawer(row)">处置记录</el-button></template></el-table-column>
        </el-table><el-empty v-if="!overview.orders.length" description="暂无指标派单" />
      </el-tab-pane>

      <el-tab-pane :label="`采集批次 ${overview.recent_batches.length}`" name="batches"><div class="section-intro"><div><strong>批次与异常行</strong><span>输入快照、成功行和异常行分别保留，异常行不会进入阈值计算。</span></div></div><el-table :data="overview.recent_batches" stripe><el-table-column prop="batch_no" label="批次号" min-width="260" /><el-table-column label="状态" width="120"><template #default="{ row }"><el-tag :type="row.status === 'IMPORTED' ? 'success' : row.status === 'PARTIAL' ? 'warning' : 'danger'" effect="plain">{{ batchStatus(row.status) }}</el-tag></template></el-table-column><el-table-column prop="accepted_rows" label="有效行" width="100" /><el-table-column prop="rejected_rows" label="异常行" width="100" /><el-table-column label="采集时间" width="190"><template #default="{ row }">{{ datetimeFormat(row.collected_at) }}</template></el-table-column></el-table></el-tab-pane>
    </el-tabs></el-card>

    <el-dialog v-model="definitionDialog" :title="definitionForm.id ? '编辑指标' : '新增指标'" width="620px"><el-form label-position="top"><div class="form-grid"><el-form-item label="指标名称"><el-input v-model="definitionForm.name" /></el-form-item><el-form-item label="指标编码"><el-input v-model="definitionForm.metric_key" placeholder="例如 network_latency_ms" /></el-form-item><el-form-item label="所属主题"><el-select v-model="definitionForm.theme"><el-option v-for="theme in overview.themes" :key="theme.theme" :label="theme.theme_label" :value="theme.theme" /></el-select></el-form-item><el-form-item label="单位"><el-input v-model="definitionForm.unit" /></el-form-item></div><el-form-item label="维度声明"><el-input v-model="definitionForm.dimensions" placeholder="device, network_element, time_slot" /><small class="muted">使用英文逗号分隔，导入批次会拒绝未声明维度。</small></el-form-item><el-form-item label="说明"><el-input v-model="definitionForm.description" type="textarea" :rows="2" /></el-form-item><el-switch v-model="definitionForm.enabled" active-text="启用" /></el-form><template #footer><el-button @click="definitionDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitDefinition">保存</el-button></template></el-dialog>
    <el-dialog v-model="sourceDialog" :title="sourceForm.id ? '编辑数据源' : '新增数据源'" width="620px"><el-form label-position="top"><div class="form-grid"><el-form-item label="数据源名称"><el-input v-model="sourceForm.name" /></el-form-item><el-form-item label="数据源编码"><el-input v-model="sourceForm.source_key" /></el-form-item><el-form-item label="类型"><el-select v-model="sourceForm.source_type"><el-option label="手工导入" value="MANUAL" /><el-option label="接口采集" value="API" /><el-option label="数据库采集" value="DATABASE" /></el-select></el-form-item><el-form-item label="调度说明"><el-input v-model="sourceForm.schedule" placeholder="例如 每 5 分钟" /></el-form-item></div><el-form-item label="接口地址 / 表名"><el-input v-model="sourceForm.endpoint" placeholder="仅填非敏感定位信息" /></el-form-item><el-switch v-model="sourceForm.enabled" active-text="启用" /></el-form><template #footer><el-button @click="sourceDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitSource">保存</el-button></template></el-dialog>
    <el-dialog v-model="ruleDialog" :title="ruleForm.id ? '编辑预警规则' : '新增预警规则'" width="680px"><el-form label-position="top"><div class="form-grid"><el-form-item label="规则名称"><el-input v-model="ruleForm.name" /></el-form-item><el-form-item label="目标指标"><el-select v-model="ruleForm.definition_id" filterable><el-option v-for="item in overview.definitions" :key="item.id" :label="`${item.theme_label} / ${item.name}`" :value="item.id" /></el-select></el-form-item><el-form-item label="策略模式"><el-radio-group v-model="ruleForm.mode"><el-radio-button value="STATIC">固定阈值</el-radio-button><el-radio-button value="DYNAMIC">动态基线</el-radio-button></el-radio-group></el-form-item><el-form-item label="判断方向"><el-radio-group v-model="ruleForm.direction"><el-radio value="ABOVE">高于</el-radio><el-radio value="BELOW">低于</el-radio></el-radio-group></el-form-item></div><div v-if="ruleForm.mode === 'STATIC'" class="form-grid"><el-form-item label="关注阈值"><el-input-number v-model="ruleForm.warning_threshold" :controls="false" /></el-form-item><el-form-item label="紧急阈值"><el-input-number v-model="ruleForm.critical_threshold" :controls="false" /></el-form-item></div><div v-else class="form-grid three"><el-form-item label="历史窗口"><el-input-number v-model="ruleForm.baseline_window" :min="3" :max="200" /></el-form-item><el-form-item label="关注偏差 σ"><el-input-number v-model="ruleForm.warning_deviation" :min="0.1" :step="0.1" /></el-form-item><el-form-item label="紧急偏差 σ"><el-input-number v-model="ruleForm.critical_deviation" :min="0.1" :step="0.1" /></el-form-item></div><el-form-item label="维度过滤（JSON）"><el-input v-model="ruleForm.dimension_filter" placeholder='例如 {"device":"核心路由器-01"}' /></el-form-item><div class="form-grid"><el-form-item label="每日生效开始"><el-time-select v-model="ruleForm.active_start" start="00:00" step="00:30" end="23:30" /></el-form-item><el-form-item label="每日生效结束"><el-time-select v-model="ruleForm.active_end" start="00:00" step="00:30" end="23:59" /></el-form-item></div><el-switch v-model="ruleForm.enabled" active-text="启用" /></el-form><template #footer><el-button @click="ruleDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitRule">保存新版本</el-button></template></el-dialog>
    <el-dialog v-model="shiftDialog" :title="shiftForm.id ? '编辑值班班次' : '新增值班班次'" width="620px"><el-form label-position="top"><div class="form-grid"><el-form-item label="班次名称"><el-input v-model="shiftForm.name" /></el-form-item><el-form-item label="值班人员"><el-select v-model="shiftForm.assignee_id"><el-option v-for="user in overview.assignees" :key="user.id" :label="`${user.name} (${user.username})`" :value="user.id" /></el-select></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="shiftForm.starts_at" type="datetime" /></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="shiftForm.ends_at" type="datetime" /></el-form-item></div><el-switch v-model="shiftForm.enabled" active-text="启用" /></el-form><template #footer><el-button @click="shiftDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitShift">保存</el-button></template></el-dialog>
    <el-drawer v-model="observationDrawer" title="观测事实链" size="620px" class="metric-observation-drawer">
      <div v-loading="detailLoading" class="observation-drawer-body"><template v-if="observationDetail">
        <div class="detail-hero"><small>{{ observationDetail.observation.definition.theme_label }} · {{ observationDetail.observation.definition.metric_key }}</small><h3>{{ observationDetail.observation.definition.name }}</h3><strong>{{ roundValue(observationDetail.observation.value) }}{{ observationDetail.observation.definition.unit }}</strong><span>{{ datetimeFormat(observationDetail.observation.observed_at) }}</span><p>{{ dimensionText(observationDetail.observation.dimensions) }}</p></div>
        <div class="fact-grid"><article><small>采集批次</small><strong>{{ observationDetail.batch.batch_no }}</strong><span>{{ observationDetail.batch.source_name }} · {{ observationDetail.batch.operator_name }}</span></article><article><small>导入结果</small><strong>{{ observationDetail.batch.accepted_rows }} / {{ observationDetail.batch.total_rows }}</strong><span>异常 {{ observationDetail.batch.rejected_rows }} 行</span></article></div>
        <el-divider content-position="left">动态基线</el-divider>
        <article v-for="baseline in observationDetail.baselines" :key="baseline.id" class="baseline-card"><div><strong>V{{ baseline.version }} · {{ baseline.algorithm }}</strong><span>{{ baseline.sample_count }} 个历史样本 / 窗口 {{ baseline.window_size }}</span></div><code>均值 {{ roundValue(baseline.mean_value) }} · σ {{ roundValue(baseline.standard_deviation) }}</code></article><el-empty v-if="!observationDetail.baselines.length" description="该观测尚无历史基线" :image-size="60" />
        <el-divider content-position="left">告警与派单</el-divider>
        <article v-for="incident in observationDetail.incidents" :key="incident.id" class="incident-card"><header><div><small>{{ incident.rule_name }} · 配置 V{{ incident.config_version }}</small><strong>{{ incident.title }}</strong></div><el-tag :type="incident.severity === 'CRITICAL' ? 'danger' : 'warning'" effect="plain">{{ incident.severity === 'CRITICAL' ? '紧急' : '关注' }}</el-tag></header><p>{{ incident.message }}</p><small>观测 {{ roundValue(incident.observed_value) }} / 阈值 {{ roundValue(incident.threshold_value) }}</small><section v-for="order in incident.orders" :key="order.id" class="linked-order"><div><strong>{{ order.title }}</strong><el-tag size="small" effect="plain">{{ order.status_label }}</el-tag></div><span>{{ order.assignee_name || '待人工指派' }}</span><el-timeline><el-timeline-item v-for="event in order.events" :key="event.id" :timestamp="datetimeFormat(event.occurred_at)" placement="top"><strong>{{ event.action_label }}</strong><p v-if="event.note">{{ event.note }}</p></el-timeline-item></el-timeline></section></article><el-empty v-if="!observationDetail.incidents.length" description="该观测未命中预警规则" :image-size="60" />
      </template></div>
    </el-drawer>
    <el-drawer v-model="orderDrawer" title="派单处置记录" size="520px" class="metric-order-drawer"><template v-if="currentOrder"><div class="order-summary"><small>{{ currentOrder.theme_label }} · {{ currentOrder.metric_name }}</small><h3>{{ currentOrder.title }}</h3><div><el-tag effect="plain">{{ currentOrder.status_label }}</el-tag><span>{{ currentOrder.assignee_name || '待人工指派' }}</span></div></div><div v-if="currentOrder.status !== 'CLOSED'" class="order-actions"><el-select v-model="orderAssignee" placeholder="选择处理人"><el-option v-for="user in overview.assignees" :key="user.id" :label="user.name" :value="user.id" /></el-select><el-button type="primary" plain @click="assignOrder">{{ currentOrder.status === 'NEW' ? '指派' : '转派' }}</el-button><el-input v-model="orderNote" type="textarea" :rows="2" placeholder="填写处置备注、原因或交接说明" /><el-button :disabled="!orderNote.trim()" @click="commentOrder">追加备注</el-button></div><el-divider content-position="left">事件时间线</el-divider><el-timeline v-loading="eventsLoading"><el-timeline-item v-for="event in orderEvents" :key="event.id" :timestamp="datetimeFormat(event.occurred_at)" placement="top"><article class="event-card"><strong>{{ event.action_label }}</strong><span>{{ event.operator_name }}</span><p v-if="event.note">{{ event.note }}</p><small v-if="event.from_status || event.to_status">{{ event.from_status || '—' }} → {{ event.to_status || '—' }}</small></article></el-timeline-item></el-timeline><el-empty v-if="!eventsLoading && !orderEvents.length" description="暂无处置事件" /></template></el-drawer>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref } from 'vue'
import * as echarts from 'echarts'
import { DataAnalysis, Refresh } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { bootstrapMetricFoundation, getMetricAnalytics, getMetricFoundationOverview, getMetricObservationDetail, getMetricOrderEvents, operateMetricDispatchOrder, saveMetricDefinition, saveMetricDutyShift, saveMetricRule, saveMetricSource, type MetricAnalytics, type MetricDataSource, type MetricDefinitionOverview, type MetricDispatchOrder, type MetricDutyShift, type MetricFoundationOverview, type MetricObservationDetail, type MetricOrderEvent, type MetricRuleOverview } from '@/api/metric-foundation'
import { datetimeFormat } from '@/utils/time'

const themeSeed = [['TROUBLESHOOTING', '监控排障'], ['SECURITY', '安全隐患'], ['COST', '成本效能'], ['DELIVERY', '客户交付'], ['NETWORK', '网络运行'], ['CAPABILITY', '能力指标'], ['MAINTENANCE', '维护优化'], ['DATA_RISK', '涉网涉数风险']]
const emptyOverview = (): MetricFoundationOverview => ({ summary: { definition_count: 0, theme_count: 0, batch_count: 0, baseline_count: 0, rule_count: 0, active_incident_count: 0, open_order_count: 0 }, themes: themeSeed.map(([theme, theme_label]) => ({ theme, theme_label, metric_count: 0 })), definitions: [], sources: [], rules: [], duty_shifts: [], assignees: [], orders: [], recent_batches: [] })
const emptyAnalytics = (): MetricAnalytics => ({ filters: { theme: '', definition_id: null, device: '', network_element: '', time_slot: '' }, dimension_options: { device: [], network_element: [], time_slot: [] }, definitions: [], selected_definition: null, theme_stats: themeSeed.map(([theme, theme_label]) => ({ theme, theme_label, metric_count: 0, observation_count: 0, average_value: null, minimum_value: null, maximum_value: null, latest_value: null, latest_unit: '', latest_observed_at: null, alert_count: 0 })), summary: { observation_count: 0, average_value: null, minimum_value: null, maximum_value: null, alert_count: 0 }, points: [] })
const overview = ref<MetricFoundationOverview>(emptyOverview())
const analytics = ref<MetricAnalytics>(emptyAnalytics())
const loading = ref(false), saving = ref(false), bootstrapping = ref(false), eventsLoading = ref(false), trendLoading = ref(false), detailLoading = ref(false)
const activeTab = ref('analytics'), calendarDate = ref(new Date())
const definitionDialog = ref(false), sourceDialog = ref(false), ruleDialog = ref(false), shiftDialog = ref(false), orderDrawer = ref(false), observationDrawer = ref(false)
const currentOrder = ref<MetricDispatchOrder | null>(null), orderEvents = ref<MetricOrderEvent[]>([]), orderAssignee = ref(''), orderNote = ref('')
const observationDetail = ref<MetricObservationDetail | null>(null)
const trendChartRef = ref<HTMLDivElement>(), analyticsFilter = ref({ theme: '', definition_id: '', device: '', network_element: '', time_slot: '', range: null as [Date, Date] | null })
let trendChart: echarts.ECharts | null = null
let chartResizeObserver: ResizeObserver | null = null
const definitionForm = ref({ id: '', name: '', metric_key: '', theme: 'TROUBLESHOOTING', unit: '', dimensions: '', description: '', enabled: true })
const sourceForm = ref({ id: '', name: '', source_key: '', source_type: 'MANUAL', endpoint: '', schedule: '', enabled: true })
const ruleForm = ref({ id: '', definition_id: '', name: '', mode: 'STATIC', direction: 'ABOVE', warning_threshold: null as number | null, critical_threshold: null as number | null, warning_deviation: 1.5, critical_deviation: 2.5, baseline_window: 5, dimension_filter: '{}', active_start: '00:00', active_end: '23:59', enabled: true })
const shiftForm = ref({ id: '', name: '', assignee_id: '', starts_at: new Date(), ends_at: new Date(Date.now() + 8 * 3600_000), enabled: true })
const selectedDay = computed(() => localDay(calendarDate.value)), selectedDayShifts = computed(() => shiftsForDay(selectedDay.value))
const filteredDefinitions = computed(() => overview.value.definitions.filter(item => !analyticsFilter.value.theme || item.theme === analyticsFilter.value.theme))
function localDay(value: Date | string) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
function shiftsForDay(day: string) { return overview.value.duty_shifts.filter(shift => localDay(shift.starts_at) <= day && localDay(shift.ends_at) >= day) }
async function loadOverview() { overview.value = (await getMetricFoundationOverview(loading)).data; await loadAnalytics() }
async function loadAnalytics() { const filter = analyticsFilter.value; const params: Record<string, unknown> = { theme: filter.theme || undefined, definition_id: filter.definition_id || undefined, device: filter.device || undefined, network_element: filter.network_element || undefined, time_slot: filter.time_slot || undefined, start: filter.range?.[0].toISOString(), end: filter.range?.[1].toISOString() }; analytics.value = (await getMetricAnalytics(params, trendLoading)).data; analyticsFilter.value.definition_id = analytics.value.filters.definition_id || ''; await renderTrendChart() }
async function bootstrapDemo() { await ElMessageBox.confirm('将保留八类主题趋势、动态基线、值班派单和告警样例。', '生成 M03 V1 验收样例', { confirmButtonText: '生成样例', cancelButtonText: '取消', type: 'info' }); overview.value = (await bootstrapMetricFoundation(bootstrapping)).data.overview; analyticsFilter.value = { theme: '', definition_id: '', device: '', network_element: '', time_slot: '', range: null }; await loadAnalytics(); window.dispatchEvent(new CustomEvent('marketing-notification-updated')); activeTab.value = 'analytics'; ElMessage.success('八类主题验收样例已生成') }
async function onThemeChange() { analyticsFilter.value.definition_id = ''; await loadAnalytics() }
async function selectTheme(theme: string) { analyticsFilter.value.theme = theme; analyticsFilter.value.definition_id = ''; await loadAnalytics() }
async function resetAnalytics() { analyticsFilter.value = { theme: '', definition_id: '', device: '', network_element: '', time_slot: '', range: null }; await loadAnalytics() }
async function openObservationDetail(id: string) { observationDetail.value = null; observationDrawer.value = true; observationDetail.value = (await getMetricObservationDetail(id, detailLoading)).data }
async function renderTrendChart() { await nextTick(); if (!trendChartRef.value) return; if (!trendChart) { trendChart = echarts.init(trendChartRef.value); chartResizeObserver = new ResizeObserver(() => trendChart?.resize()); chartResizeObserver.observe(trendChartRef.value) } const points = analytics.value.points; trendChart.setOption({ animationDuration: 350, color: ['#087c79', '#536b75', '#d19a43', '#c44936'], grid: { left: 48, right: 30, top: 45, bottom: 58 }, tooltip: { trigger: 'axis' }, legend: { top: 8, right: 10, data: ['观测值', '动态基线', '关注阈值', '紧急阈值'] }, xAxis: { type: 'category', boundaryGap: false, data: points.map(point => datetimeFormat(point.observed_at)), axisLabel: { rotate: 20, color: '#657985' } }, yAxis: { type: 'value', scale: true, splitLine: { lineStyle: { color: '#e2e8ea' } } }, series: [{ name: '观测值', type: 'line', data: points.map(point => ({ value: point.value, itemStyle: point.alert ? { color: point.alert.severity === 'CRITICAL' ? '#c44936' : '#d19a43', borderWidth: 3 } : undefined })), symbolSize: 8, lineStyle: { width: 3 } }, { name: '动态基线', type: 'line', data: points.map(point => point.baseline_mean), connectNulls: true, symbol: 'none', lineStyle: { type: 'dashed', width: 2 } }, { name: '关注阈值', type: 'line', data: points.map(point => point.warning_threshold), connectNulls: true, symbol: 'none', lineStyle: { type: 'dashed', width: 1.5 } }, { name: '紧急阈值', type: 'line', data: points.map(point => point.critical_threshold), connectNulls: true, symbol: 'none', lineStyle: { type: 'dashed', width: 1.5 } }] }, true); trendChart.off('click'); trendChart.on('click', (event) => { if (typeof event.dataIndex === 'number' && points[event.dataIndex]) openObservationDetail(points[event.dataIndex].id) }) }
function openDefinitionDialog(row?: MetricDefinitionOverview) { definitionForm.value = row ? { id: row.id, name: row.name, metric_key: row.metric_key, theme: row.theme, unit: row.unit, dimensions: row.dimensions_schema.join(', '), description: row.description, enabled: row.enabled } : { id: '', name: '', metric_key: '', theme: 'TROUBLESHOOTING', unit: '', dimensions: '', description: '', enabled: true }; definitionDialog.value = true }
async function submitDefinition() { const form = definitionForm.value; await saveMetricDefinition({ metric_key: form.metric_key, name: form.name, theme: form.theme, unit: form.unit, description: form.description, dimensions_schema: form.dimensions.split(',').map(item => item.trim()).filter(Boolean), enabled: form.enabled }, form.id || undefined, saving); definitionDialog.value = false; await loadOverview(); ElMessage.success('指标配置已保存') }
function openSourceDialog(row?: MetricDataSource) { sourceForm.value = row ? { id: row.id, name: row.name, source_key: row.source_key, source_type: row.source_type, endpoint: String(row.config_snapshot.endpoint || row.config_snapshot.table || ''), schedule: String(row.config_snapshot.schedule || ''), enabled: row.enabled } : { id: '', name: '', source_key: '', source_type: 'MANUAL', endpoint: '', schedule: '', enabled: true }; sourceDialog.value = true }
async function submitSource() { const form = sourceForm.value; await saveMetricSource({ source_key: form.source_key, name: form.name, source_type: form.source_type, config_snapshot: { endpoint: form.endpoint, schedule: form.schedule }, enabled: form.enabled }, form.id || undefined, saving); sourceDialog.value = false; await loadOverview(); ElMessage.success('数据源配置已保存') }
function openRuleDialog(row?: MetricRuleOverview) { ruleForm.value = row ? { id: row.id, definition_id: row.definition_id, name: row.name, mode: row.mode, direction: row.direction, warning_threshold: row.warning_threshold, critical_threshold: row.critical_threshold, warning_deviation: row.warning_deviation, critical_deviation: row.critical_deviation, baseline_window: row.baseline_window, dimension_filter: JSON.stringify(row.dimension_filter || {}), active_start: row.active_windows[0]?.start || '00:00', active_end: row.active_windows[0]?.end || '23:59', enabled: row.enabled } : { id: '', definition_id: overview.value.definitions[0]?.id || '', name: '', mode: 'STATIC', direction: 'ABOVE', warning_threshold: null, critical_threshold: null, warning_deviation: 1.5, critical_deviation: 2.5, baseline_window: 5, dimension_filter: '{}', active_start: '00:00', active_end: '23:59', enabled: true }; ruleDialog.value = true }
async function submitRule() { let dimensions: Record<string, string>; try { dimensions = JSON.parse(ruleForm.value.dimension_filter || '{}') } catch { ElMessage.error('维度过滤必须是合法 JSON'); return } const form = ruleForm.value; await saveMetricRule({ definition_id: form.definition_id, name: form.name, mode: form.mode, direction: form.direction, warning_threshold: form.warning_threshold, critical_threshold: form.critical_threshold, warning_deviation: form.warning_deviation, critical_deviation: form.critical_deviation, baseline_window: form.baseline_window, dimension_filter: dimensions, active_windows: [{ start: form.active_start, end: form.active_end }], enabled: form.enabled }, form.id || undefined, saving); ruleDialog.value = false; await loadOverview(); ElMessage.success('预警规则新版本已保存') }
function openShiftDialog(row?: MetricDutyShift) { shiftForm.value = row ? { id: row.id, name: row.name, assignee_id: row.assignee_id, starts_at: new Date(row.starts_at), ends_at: new Date(row.ends_at), enabled: row.enabled } : { id: '', name: '', assignee_id: overview.value.assignees[0]?.id || '', starts_at: new Date(calendarDate.value), ends_at: new Date(new Date(calendarDate.value).getTime() + 8 * 3600_000), enabled: true }; shiftDialog.value = true }
async function submitShift() { const form = shiftForm.value; await saveMetricDutyShift({ name: form.name, assignee_id: form.assignee_id, starts_at: form.starts_at.toISOString(), ends_at: form.ends_at.toISOString(), enabled: form.enabled }, form.id || undefined, saving); shiftDialog.value = false; await loadOverview(); ElMessage.success('值班班次已保存') }
async function operateOrder(row: MetricDispatchOrder, action: 'CLAIM' | 'START' | 'RESOLVE' | 'CLOSE') { await operateMetricDispatchOrder(row.id, { action }); await loadOverview(); ElMessage.success({ CLAIM: '派单已认领', START: '已开始处理', RESOLVE: '派单已解决', CLOSE: '派单已关闭' }[action]) }
async function openOrderDrawer(row: MetricDispatchOrder, mode?: 'assign') { currentOrder.value = row; orderAssignee.value = row.assignee_id || ''; orderNote.value = mode === 'assign' ? '人工指派' : ''; orderDrawer.value = true; orderEvents.value = (await getMetricOrderEvents(row.id, eventsLoading)).data }
async function assignOrder() { if (!currentOrder.value || !orderAssignee.value) { ElMessage.warning('请选择处理人'); return } const action = currentOrder.value.status === 'NEW' ? 'ASSIGN' : 'TRANSFER'; await operateMetricDispatchOrder(currentOrder.value.id, { action, assignee_id: orderAssignee.value, note: orderNote.value }); await refreshDrawer('派单处理人已更新') }
async function commentOrder() { if (!currentOrder.value || !orderNote.value.trim()) return; await operateMetricDispatchOrder(currentOrder.value.id, { action: 'COMMENT', note: orderNote.value.trim() }); await refreshDrawer('处置备注已追加') }
async function refreshDrawer(message: string) { const id = currentOrder.value?.id; await loadOverview(); currentOrder.value = overview.value.orders.find(row => row.id === id) || null; if (id) orderEvents.value = (await getMetricOrderEvents(id, eventsLoading)).data; orderNote.value = ''; window.dispatchEvent(new CustomEvent('marketing-notification-updated')); ElMessage.success(message) }
function metricValue(row: MetricDefinitionOverview) { return row.latest_value === null ? '—' : `${roundValue(row.latest_value)}${row.unit}` }
function roundValue(value: number) { return Number.isInteger(value) ? value : Number(value.toFixed(2)) }
function displayNumber(value: number | null) { return value === null ? '—' : String(roundValue(value)) }
function dimensionText(dimensions: Record<string, string>) { const content = Object.entries(dimensions).map(([key, value]) => `${key}: ${value}`).join(' · '); return content || '全局维度' }
function batchStatus(status: string) { return { IMPORTED: '导入成功', PARTIAL: '部分成功', FAILED: '导入失败' }[status] || status }
onBeforeUnmount(() => { chartResizeObserver?.disconnect(); trendChart?.dispose(); trendChart = null })
loadOverview()
</script>

