.analytics-shell { min-height: 520px; }.analytics-filter { display: grid; grid-template-columns: 130px minmax(170px, 1fr) repeat(3, minmax(110px, 130px)) minmax(260px, 300px) 64px 64px; gap: 8px; margin-bottom: 14px; padding: 12px; border: 1px solid var(--line); background: #f8fbfb; }.analytics-filter > * { min-width: 0; }.analytics-filter :deep(.el-select) { width: 100%; min-width: 0; }.analytics-filter :deep(.analytics-time-range.el-date-editor) { --el-date-editor-width: 100%; width: 100% !important; min-width: 0; max-width: 300px; box-sizing: border-box; }.analytics-filter > .el-button + .el-button { margin-left: 0; }.theme-stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 12px; }.theme-stat-grid button { display: grid; gap: 4px; min-height: 84px; padding: 12px 14px; text-align: left; color: var(--ink); border: 1px solid var(--line); border-radius: 4px; background: #fff; cursor: pointer; transition: border-color .16s, transform .16s; }.theme-stat-grid button:hover { transform: translateY(-1px); border-color: #7ca9a6; }.theme-stat-grid button.active { border-color: var(--cyan); box-shadow: inset 3px 0 var(--cyan); background: #f3fafa; }.theme-stat-grid button span, .theme-stat-grid button small { color: var(--muted); }.theme-stat-grid button strong { font: 22px 'SFMono-Regular', Consolas, monospace; }.trend-summary { display: grid; grid-template-columns: repeat(4, 1fr); border: 1px solid var(--line); background: var(--line); gap: 1px; }.trend-summary article { display: grid; gap: 5px; padding: 12px 16px; background: #fff; }.trend-summary article.alerting { box-shadow: inset 0 3px var(--orange); }.trend-summary span { color: var(--muted); font-size: 12px; }.trend-summary strong { font: 20px 'SFMono-Regular', Consolas, monospace; }.trend-panel { position: relative; margin: 12px 0; padding: 14px; border: 1px solid var(--line); background: #fff; }.trend-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }.trend-heading h3 { margin: 3px 0 0; }.trend-heading small { color: var(--cyan); font-family: monospace; }.trend-heading > span { color: var(--muted); font-size: 12px; }.trend-chart { height: 350px; }.trend-panel > .el-empty { position: absolute; inset: 82px 0 0; background: rgb(255 255 255 / 80%); }.observation-table { border: 1px solid var(--line); }.observation-drawer-body { min-height: 300px; padding: 0 20px 30px; overflow-y: auto; }.detail-hero { display: grid; grid-template-columns: 1fr auto; gap: 5px 16px; padding: 16px; border-left: 4px solid var(--cyan); background: #f3f8f8; }.detail-hero h3, .detail-hero p { grid-column: 1 / -1; margin: 0; }.detail-hero > small, .detail-hero > span, .detail-hero p { color: var(--muted); }.detail-hero > strong { color: var(--cyan); font: 26px 'SFMono-Regular', Consolas, monospace; }.fact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }.fact-grid article, .baseline-card { padding: 12px; border: 1px solid var(--line); background: #fff; }.fact-grid article { display: grid; gap: 5px; }.fact-grid small, .fact-grid span, .baseline-card span, .incident-card small, .linked-order > span { color: var(--muted); font-size: 12px; }.baseline-card { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }.baseline-card > div { display: grid; gap: 4px; }.baseline-card code { color: var(--cyan); }.incident-card { margin-bottom: 12px; padding: 14px; border: 1px solid #e7cbbb; border-left: 3px solid var(--orange); background: #fffaf7; }.incident-card > header, .linked-order > div { display: flex; align-items: center; justify-content: space-between; gap: 12px; }.incident-card header > div { display: grid; gap: 4px; }.incident-card > p { color: #425964; }.linked-order { margin-top: 12px; padding: 12px; border: 1px solid var(--line); background: #fff; }.linked-order > div { margin-bottom: 4px; }.linked-order :deep(.el-timeline) { margin-top: 14px; padding-left